import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"How do the adapter and the ESPHome dashboard relate?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/05.hintergrund/01.adapter-und-dashboard.md"},"headers":[],"relativePath":"adapter/esphome/hintergrund/adapter-und-dashboard.md","filePath":"adapter/esphome/hintergrund/adapter-und-dashboard.md","lastUpdated":null}'),r={name:"adapter/esphome/hintergrund/adapter-und-dashboard.md"};function h(s,e,n,i,p,l){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="how-do-the-adapter-and-the-esphome-dashboard-relate" tabindex="-1">How do the adapter and the ESPHome dashboard relate? <a class="header-anchor" href="#how-do-the-adapter-and-the-esphome-dashboard-relate" aria-label="Permalink to &quot;How do the adapter and the ESPHome dashboard relate?&quot;">​</a></h1><p><a id="use-esphome-home-assistant-run"></a></p><h2 id="can-i-use-esphome-without-home-assistant-and-run-the-dashboard-in-the-adapter" tabindex="-1">Can I use ESPHome without Home Assistant and run the dashboard in the adapter? <a class="header-anchor" href="#can-i-use-esphome-without-home-assistant-and-run-the-dashboard-in-the-adapter" aria-label="Permalink to &quot;Can I use ESPHome without Home Assistant and run the dashboard in the adapter?&quot;">​</a></h2><p>Yes. ESPHome does not need Home Assistant. The adapter controls the devices over the Native API and can bring the ESPHome Dashboard along, where you write, compile and flash YAML files.</p><p>You switch the dashboard on in the tab &quot;ESPHome Dashboard&quot; with &quot;Enable ESPHome Dashboard&quot;, it is off by default. Adapter and dashboard work separately: a device in the dashboard is not automatically in the adapter, and vice versa.</p><p><strong>See also:</strong> <a href="./../erste-schritte/dashboard-einschalten#dashboard-tab-not-open-localhost">Open the dashboard tab</a> · <a href="#adapter-dashboard-show-device-status">Why the status differs</a></p><p><a id="adapter-dashboard-show-device-status"></a></p><h2 id="why-do-adapter-and-dashboard-show-the-device-status-differently" tabindex="-1">Why do adapter and dashboard show the device status differently? <a class="header-anchor" href="#why-do-adapter-and-dashboard-show-the-device-status-differently" aria-label="Permalink to &quot;Why do adapter and dashboard show the device status differently?&quot;">​</a></h2><p>Adapter and dashboard check the device status independently. The adapter shows whether its API connection to the device stands (<code>info._online</code>). The dashboard checks on its own whether it finds the device on the network, and needs mDNS for that.</p><p>So a device can be online in the adapter and offline in the dashboard, especially when:</p><ul><li>the device is in another network or VLAN than the ioBroker host,</li><li>ioBroker runs in Docker without the host network,</li><li>the router does not resolve mDNS names.</li></ul><p>For control from ioBroker only the status in the adapter counts. A device that is only in the adapter gets into the dashboard via &quot;Adopt&quot; or a new YAML.</p><p><strong>See also:</strong> <a href="./../anleitungen/geraete-entdecken#devices-another-vlan-iobroker-runs">Devices in another VLAN or Docker</a></p>',13)])])}const b=a(r,[["render",h]]);export{u as __pageData,b as default};
